jQuery(document).ready(function($){function SettingsRow(id,dependencies={}){this.id=id,this.settingsPage=null,this.dependencies=dependencies,this.init=function(settingsPage){this.settingsPage=settingsPage,this.$getRow(!1).on("change",()=>this.settingsPage.renderSettings())},this.show=function(){this.$getRow().closest("tr").show()},this.hide=function(){this.$getRow().closest("tr").hide()},this.isChecked=function(){return this.$getRow().is(":checked")},this.isValueEqual=function(value){return this.$getRow().val()===value},this.shouldBeShown=function(){let pass=!0;for(var[rowID,value]of Object.entries(this.dependencies)){const row=this.settingsPage.getRowById(rowID);if(row)if(":checked"===value)pass=pass&&row.isChecked();else if(":unchecked"===value)pass=pass&&!row.isChecked();else if("string"==typeof value)pass=pass&&row.isValueEqual(value);else if(value.constructor===Array){let _pass=!1;value.forEach(_value=>{_pass=_pass||row.isValueEqual(_value)}),pass=pass&&_pass}}return pass},this.$getRow=function(any=!0){let input=$('[name^="'+this.settingsPage.prefix+this.id+'"]');return input=any&&input.is(":radio")?input.filter(":checked"):input}}if(void 0!==window.customPriceDisplaySettingsConditionals){const settingRows=[],settingsPage=(Object.entries(window.customPriceDisplaySettingsConditionals).forEach(([key,dependencies])=>{"object"!=typeof dependencies&&(dependencies={}),Array.isArray(dependencies)&&(dependencies={}),settingRows.push(new SettingsRow(key,dependencies))}),new function(){this.prefix="",this.rows=[],this.init=function(rows){this.rows=rows,this.renderSettings()},this.getRowById=function(id){return this.rows.find(row=>row.id=id)},this.renderSettings=function(){this.rows.forEach(row=>row.shouldBeShown()?row.show():row.hide())}});settingRows.forEach(row=>row.init(settingsPage)),settingsPage.init(settingRows)}});
